set -euo pipefail; python3 - <<'PY'
import json, pathlib, sqlite3
root=pathlib.Path('/workspace/omega_runtime')
print('===RELEASE===')
meta=root/'CURRENT_RELEASE.json'
if meta.exists():
    d=json.loads(meta.read_text()); print('CURRENT_RELEASE',json.dumps({k:d.get(k) for k in ('omega_head','release_dir','activated_at','source')},separators=(',',':')))
else: print('CURRENT_RELEASE MISSING')
cur=root/'current'
print('CURRENT_LINK',cur.resolve() if cur.exists() else 'MISSING')
rels=root/'releases'
if rels.exists(): print('RELEASES',','.join(sorted(p.name for p in rels.iterdir() if p.is_dir())[-12:]))
print('===SUPERVISOR===')
s=root/'state/SUPERVISOR_STATUS.json'
if s.exists():
    d=json.loads(s.read_text()); print('SUPERVISOR',json.dumps({'updated_at':d.get('updated_at'),'pid':d.get('pid'),'repo_root':d.get('repo_root'),'children':{k:{'alive':v.get('alive'),'returncode':v.get('returncode')} for k,v in (d.get('children') or {}).items()}},separators=(',',':')))
else: print('SUPERVISOR MISSING')
print('===GRID===' )
g=root/'state/STATUS.json'
if g.exists():
    d=json.loads(g.read_text()); print('GRID_STATUS',json.dumps({k:d.get(k) for k in ('updated_at','runtime_epoch_id','frame_id','state')},separators=(',',':')))
else: print('GRID_STATUS MISSING')
print('===OUTER===')
o=root/'state/outer_bridge/OUTER_WORKER_STATUS.json'
if o.exists():
    d=json.loads(o.read_text()); print('OUTER_STATUS',json.dumps({k:d.get(k) for k in ('updated_at','state','processed','unknown','errors')},separators=(',',':')))
else: print('OUTER_STATUS MISSING')
print('===DB===' )
for p in (root/'state/omega_runtime.sqlite3', root/'data/omega_unified.db'):
    if not p.exists(): print('DB_MISSING',p); continue
    print('DB',p,'bytes',p.stat().st_size)
    try:
      con=sqlite3.connect(f'file:{p}?mode=ro',uri=True); names={r[0] for r in con.execute("select name from sqlite_master where type='table'")}
      out={}
      for t in ('frame','task','effect','observation','bridge_message'):
        if t in names: out[t]=con.execute(f'select count(*) from {t}').fetchone()[0]
      con.close(); print('COUNTS',json.dumps(out,separators=(',',':')))
    except Exception as e: print('DB_READ_ERROR',type(e).__name__)
